<?php
/** Proof — scope and rights (spec "Proof", 1): a personal response is its owner's alone (a direct URL → 404 "Canned response not found."); a queue's shows to its holders; a global one to everyone with tickets.work; a collaborator and a requester are refused with "You may not work tickets here."; support cannot share. */
require __DIR__ . '/lib.php';
$W = world();
$marco = as_member(27); $lena = as_member(28); $priya = as_member(26); $colin = as_member(29); $owner = as_member(1);
echo "1. Saving\n";
$mine = mkcanned($marco, ['title' => 'SMOKE Marco private', 'body' => 'Hi {{requester.first_name}}, Marco here.', 'scope' => 'personal', 'folder' => 'Mine']);
ok($mine > 0 && (int) canned_row($mine)['owner_member_id'] === 27 && canned_row($mine)['folder'] === 'Mine', 'Marco saves a personal response');
[$c, $b] = act($marco, '/canned/save.php', ['title' => 'SMOKE Marco global', 'body' => 'x', 'scope' => 'global']);
ok($c === 403 && msg($b) === 'Sharing with everyone needs the Lead role.', 'Marco\'s scope=global: 403');
[$c, $b] = act($marco, '/canned/save.php', ['title' => 'SMOKE Marco queue', 'body' => 'x', 'scope' => 'queue', 'queue' => $W['it']]);
ok($c === 403 && msg($b) === 'Sharing with a queue needs its lead.', 'Marco\'s scope=queue for IT (he is no lead): 403');
$itq = mkcanned($lena, ['title' => 'SMOKE IT queue reply', 'body' => 'The IT desk has your {{ticket.number}}.', 'scope' => 'queue', 'queue' => $W['it'], 'side_effects' => ['status' => 'pending', 'add_tags' => 'hardware']]);
ok($itq > 0 && canned_row($itq)['scope'] === 'queue' && (int) canned_row($itq)['queue_id'] === $W['it'], 'Lena (IT\'s lead) saves a queue response for IT');
[$c, $b] = act($lena, '/canned/save.php', ['title' => 'SMOKE Facilities queue', 'body' => 'x', 'scope' => 'queue', 'queue' => $W['fac']]);
ok($c === 422 && isset(fields($b)['queue']), 'for Facilities, which Lena does not hold: 422');
$fac = (int) one("INSERT INTO canned_responses (title, body_text, scope, queue_id) VALUES ('SMOKE Facilities only', 'x', 'queue', :q) RETURNING id", ['q' => $W['fac']]);
$global = mkcanned($lena, ['title' => 'SMOKE Everyone', 'body' => 'Thanks, {{requester.name}}. {{agent.signature}}', 'scope' => 'global', 'side_effects' => json_encode(['priority' => 'high', 'assign' => 'me'])]);
ok($global > 0 && canned_row($global)['scope'] === 'global' && json_decode(canned_row($global)['side_effects'], true) == ['priority' => 'high', 'assign' => 'me'], 'Lena saves a global one with side-effects as JSON (the agent\'s way)');
$since = last_activity_id();
[$c, $b] = act($lena, '/canned/save.php', ['canned' => $global, 'folder' => 'Shared']);
$l = activity('canned.update', $since);
ok($c === 200 && canned_row($global)['folder'] === 'Shared' && canned_row($global)['body_text'] !== 'x' && count($l) === 1 && !str_contains((string) $l[0]['after'], 'Thanks'), 'canned_update keeps the body it was not sent; the log never carries the body');
echo "2. Who sees what\n";
$titles = fn (string $jar) => array_map(fn ($c) => $c['title'], screen($jar, '/canned/')[1]['responses'] ?? []);
$m = $titles($marco);
ok(in_array('SMOKE Marco private', $m, true) && in_array('SMOKE IT queue reply', $m, true) && in_array('SMOKE Everyone', $m, true) && !in_array('SMOKE Facilities only', $m, true), 'Marco: his own, IT\'s, everyone\'s — not Facilities\'');
$l = $titles($lena);
ok(!in_array('SMOKE Marco private', $l, true) && in_array('SMOKE IT queue reply', $l, true) && !in_array('SMOKE Facilities only', $l, true), 'Lena: not Marco\'s private one, not Facilities\' (view_all is not holding)');
$r = page($lena, '/canned/' . $mine . '/edit');
ok($r['code'] === 404 && str_contains($r['body'], 'Canned response not found.'), 'a direct URL to Marco\'s private one: 404 "Canned response not found."');
$r = page($priya, '/canned/');
ok($r['code'] === 403 && str_contains($r['body'], 'You may not work tickets here.'), 'Priya: 403 "You may not work tickets here."');
ok(page($colin, '/canned/')['code'] === 403, 'Colin (collaborator, no tickets.work): 403 — the view admits holders of tickets.work only');
$body = page($marco, '/canned/')['body'];
ok(str_contains($body, 'id="canned-group-mine"') && str_contains($body, 'id="canned-group-queue-' . $W['it'] . '"') && str_contains($body, 'id="canned-group-global"') && str_contains($body, 'id="canned-card-' . $mine . '-edit"') && !str_contains($body, 'id="canned-card-' . $itq . '-edit"'), 'the page: Mine · IT help · Everyone; Edit on his own, not on the queue\'s');
ok(str_contains($body, '→ Pending') && str_contains($body, '+hardware') && str_contains($body, '↑ High') && str_contains($body, 'assign me'), 'side-effect chips read → Pending, +hardware, ↑ High, assign me');
[$c, $d] = screen($marco, '/canned/?q=desk');
ok(count($d['responses']) === 1 && $d['responses'][0]['title'] === 'SMOKE IT queue reply', 'search by words in the body');
[$c, $d] = screen($marco, '/canned/?folder=Shared');
ok(count($d['responses']) === 1 && $d['responses'][0]['title'] === 'SMOKE Everyone', 'the folder filter');
$body = page($colin, '/canned/')['body'];
echo "3. Changing and deleting\n";
[$c, $b] = act($marco, '/canned/save.php', ['canned' => $itq, 'title' => 'renamed by Marco']);
ok($c === 403, 'support changing the queue\'s: 403');
[$c, $b] = act($marco, '/canned/delete.php', ['canned' => $global]);
ok($c === 403, 'support deleting the global one: 403');
$since = last_activity_id();
[$c, $b] = act($lena, '/canned/save.php', ['canned' => $itq, 'title' => 'SMOKE IT queue reply (renamed)']);
ok($c === 200 && canned_row($itq)['title'] === 'SMOKE IT queue reply (renamed)', 'the lead changes a queue response');
$empty = (int) one('SELECT count(*) FROM canned_responses WHERE archived_at IS NULL');
[$c, $b] = act($marco, '/canned/delete.php', ['canned' => $mine]);
ok($c === 200 && canned_row($mine)['archived_at'] !== null && count(activity('canned.delete', $since)) === 1 && ($b['location'] ?? '') === '/canned/?notice=deleted', 'Marco deletes his own: archived, logged, lands on the list');
ok(!in_array('SMOKE Marco private', $titles($marco), true), 'and it is off his list');
q("UPDATE canned_responses SET archived_at = now() WHERE title LIKE 'SMOKE%' AND id <> :g", ['g' => $global]);
q("UPDATE canned_responses SET archived_at = now() WHERE id = :g", ['g' => $global]);
$body = page($marco, '/canned/')['body'];
ok(str_contains($body, 'id="canned-empty"') && str_contains($body, 'write one from a reply you keep typing'), 'empty: the sentence');
q("UPDATE canned_responses SET archived_at = NULL WHERE id IN (:a, :b)", ['a' => $itq, 'b' => $global]);
finish();
